// Builds brand/master/mark.svg (houses + ground arc + ND monogram) on the 1000-unit grid.
// The left half is drawn, the right half is generated by mirroring about x = 500.
import { writeFileSync } from "node:fs";
import ClipperLib from "clipper-lib";
import { f, bez, split, flatten, mirrorPt } from "./geom.mjs";

const CX = 500;
const m = (p) => mirrorPt(p, CX);

// ---- ground arc: lower edge is one symmetric cubic (tip to tip) ----
const TIP = [18, 542.5];
const ARC = { x1: 0, y1: 0 };
{
  const samples = [[350, 515], [288.5, 516.5], [232.5, 518.5], [180.5, 522.5]];
  let best = 1e9;
  for (let x1 = 80; x1 <= 480; x1 += 2)
    for (let y1 = 480; y1 <= 520; y1 += 0.5) {
      const p = [TIP, [x1, y1], [1000 - x1, y1], m(TIP)];
      let err = 0;
      for (const [sx, sy] of samples) {
        let d = 1e9;
        for (let i = 0; i <= 200; i++) {
          const q = bez(...p, i / 200);
          d = Math.min(d, Math.hypot(q[0] - sx, q[1] - sy));
        }
        err += d * d;
      }
      if (err < best) { best = err; ARC.x1 = x1; ARC.y1 = y1; }
    }
}
const L = [TIP, [ARC.x1, ARC.y1], [1000 - ARC.x1, ARC.y1], m(TIP)];
// t where the lower edge reaches the inner wall x = 350
let tw = 0;
for (let lo = 0, hi = 0.5; ; ) {
  tw = (lo + hi) / 2;
  if (bez(...L, tw)[0] > 350) hi = tw; else lo = tw;
  if (hi - lo < 1e-9) break;
}
const [Lleft] = split(...L, tw); // tip -> wall base (350, ~515)
const baseY = Lleft[3][1];

// upper edge of the crescent: tip -> (105, 516), tangent follows the lower edge at the tip
let U = null;
{
  const dirx = ARC.x1 - TIP[0], diry = ARC.y1 - TIP[1], n = Math.hypot(dirx, diry);
  let best = 1e9;
  for (let a = 5; a <= 70; a += 1)
    for (let b = 5; b <= 70; b += 1) {
      const p = [TIP, [TIP[0] + (dirx / n) * a, TIP[1] + (diry / n) * a], [105 - b, 516 + b * 0.1], [105, 516]];
      let d = 1e9;
      for (let i = 0; i <= 200; i++) { const q = bez(...p, i / 200); d = Math.min(d, Math.hypot(q[0] - 52.5, q[1] - 529.5)); }
      if (d < best) { best = d; U = p; }
    }
}

// ---- houses ----
const cs = 0.684; // center roof slope
const roofOuter = (x) => 253 + cs * Math.abs(CX - x);
const apexL = [230, 285];
const wallY = apexL[1] + 0.47 * (230 - 105); // left roof meets the wall
const jx = (253 + cs * CX - apexL[1] + 0.355 * apexL[0]) / (cs + 0.355); // junction x
const junction = [jx, roofOuter(jx)];
const innerY = 293 + cs * 150; // inner roof meets the inner wall x = 350

const P = (p) => `${f(p[0])} ${f(p[1])}`;
const C = (a, b, c) => `C${P(a)} ${P(b)} ${P(c)}`;

const chimney = { l: 572, r: 620, top: 262 };
// outline, counter-clockwise from the outer apex, left half then mirrored right half
const outline =
  `M${P([CX, 253])}L${P(junction)}L${P(apexL)}L${P([105, wallY])}L${P([105, 516])}` +
  C(U[2], U[1], U[0]) + // wall -> tip
  C(Lleft[1], Lleft[2], Lleft[3]) + // tip -> base of inner wall
  `L${P([350, innerY])}L${P([CX, 293])}L${P(m([350, innerY]))}L${P(m([350, baseY]))}` +
  C(m(Lleft[2]), m(Lleft[1]), m(Lleft[0])) + // base -> right tip
  C(m(U[1]), m(U[2]), m(U[3])) + // tip -> right wall
  `L${P(m([105, wallY]))}L${P(m(apexL))}L${P(m(junction))}` +
  `L${P([chimney.r, roofOuter(chimney.r)])}L${P([chimney.r, chimney.top])}L${P([chimney.l, chimney.top])}` +
  `L${P([chimney.l, roofOuter(chimney.l)])}Z`;

// opening in the left house (drawn once, mirrored for the right)
const holeTopY = (x) => apexL[1] + 28.3 + 0.355 * (x - 230);
const hx = (253 + cs * CX - (holeTopY(0))) / (cs + 0.355); // hole top meets the center roof line
const hole = [
  [232.5, holeTopY(232.5)], [232.5, 490], [299, 484], [299, 426], [268, 426], [268, roofOuter(268)], [hx, roofOuter(hx)],
];
const holePath = (pts) => `M${pts.map(P).join("L")}Z`;
const housePath = outline + holePath(hole) + holePath(hole.map(m).reverse());

// ---- ND monogram: strokes (width 65 in design px) expanded to fills with Clipper ----
// Design coords are crop pixels of the original at 6 px per unit around (400,330); shifted to center on the axis.
const SHIFT = -7.5;
const T = ([x, y]) => [400 + x / 6 + SHIFT, 330 + y / 6];
let SW = 65 / 6;
const SC = 100;
const toClip = (pts) => pts.map(([x, y]) => ({ X: Math.round(x * SC), Y: Math.round(y * SC) }));
const solids = [];

function pathPts(cmds) {
  const pts = [];
  let cur = null;
  for (const c of cmds) {
    if (c[0] === "M" || c[0] === "L") { cur = T(c[1]); pts.push(cur); }
    else { const q = flatten(cur, T(c[1]), T(c[2]), T(c[3]), 40); pts.push(...q); cur = T(c[3]); }
  }
  return pts;
}
const co = new ClipperLib.ClipperOffset(2, 0.05 * SC);
function stroke(cmds) {
  co.Clear();
  co.AddPath(toClip(pathPts(cmds)), ClipperLib.JoinType.jtMiter, ClipperLib.EndType.etOpenButt);
  const out = new ClipperLib.Paths();
  co.Execute(out, (SW / 2) * SC);
  solids.push(...out);
}
const poly = (pts) => solids.push(toClip(pts.map(T)));
const M = (x, y) => ["M", [x, y]], Ln = (x, y) => ["L", [x, y]], Cb = (a, b, c) => ["C", a, b, c];

function buildMonogram(widthPx) {
  SW = widthPx / 6;
  solids.length = 0;
  // building bars, slot and block
  poly([[455, 97], [835, 97], [835, 160], [455, 160]]);
  poly([[610, 97], [835, 97], [835, 380], [610, 380]]);
  poly([[455, 97], [520, 97], [520, 550], [455, 490]]);
  poly([[610, 380], [680, 380], [680, 710], [610, 650]]);
  poly([[300, 328], [455, 243], [455, 320], [352, 377], [352, 433], [290, 421], [288, 350]]);
  poly([[195, 470], [285, 470], [285, 540], [250, 545], [215, 575], [195, 615]]);
  // N stem, base slab, arch
  stroke([M(317, 540), Ln(317, 1052)]);
  stroke([M(130, 1052), Ln(350, 1052)]);
  stroke([M(162, 1052), Ln(162, 872), Cb([162, 790], [215, 747], [317, 747])]);
  // diagonal ribbon wrapping into the D's inner bowl
  stroke([M(240, 502), Ln(300, 502), Cb([355, 502], [395, 530], [430, 562]), Ln(690, 822), Cb([735, 867], [770, 893], [835, 893]), Cb([925, 893], [970, 800], [970, 700]), Cb([970, 590], [920, 510], [802, 510])]);
  stroke([M(802, 475), Ln(802, 893)]);
  // outer ribbon: under the N diagonal, around the bottom and up the D
  stroke([M(317, 747), Cb([400, 747], [450, 790], [500, 845]), Ln(600, 950), Cb([680, 1035], [760, 1052], [840, 1052]), Cb([1000, 1052], [1128, 900], [1128, 700]), Cb([1128, 500], [1010, 353], [850, 353]), Ln(700, 353)]);

  const cp = new ClipperLib.Clipper();
  cp.AddPaths(solids, ClipperLib.PolyType.ptSubject, true);
  const merged = new ClipperLib.Paths();
  cp.Execute(ClipperLib.ClipType.ctUnion, merged, ClipperLib.PolyFillType.pftNonZero, ClipperLib.PolyFillType.pftNonZero);
  const monoPath = merged.map((p) => `M${p.map((q) => `${f(q.X / SC)} ${f(q.Y / SC)}`).join("L")}Z`).join("");
  return monoPath;
}
writeFileSync("brand/master/mark.svg",
`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 1000">
<path id="houses" fill-rule="evenodd" d="${housePath}"/>
<path id="monogram" fill-rule="evenodd" d="${buildMonogram(65)}"/>
</svg>
`);
// heavier-stroke monogram for favicon sizes, where the 65 px ribbons would turn to mush
writeFileSync("brand/master/monogram-bold.svg",
`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 1000">
<path id="monogram-bold" fill-rule="evenodd" d="${buildMonogram(100)}"/>
</svg>
`);
// heaviest cut, used only for the 16 px favicon entry
writeFileSync("brand/master/monogram-xs.svg",
`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 1000">
<path id="monogram-xs" fill-rule="evenodd" d="${buildMonogram(118)}"/>
</svg>
`);
console.log("arc ctrl", ARC, "junction", junction.map(f), "wallY", f(wallY), "baseY", f(baseY), "hx", f(hx));
